// Real brand logos from apps/console/public/brand/logos embedded as Base64 Data URIs

export const BRAND_LOGO_DATA_URIS: Record<string, string> = {
  "grok": "data:image/png;base64,",
  "factory": "data:image/png;base64,",
  "droid-generic": "data:image/png;base64,",
  "droid-claude": "data:image/png;base64,",
  "droid-openai": "data:image/png;base64,",
  "forge": "data:image/png;base64,",
  "opencode": "data:image/png;base64,",
  "codex": "data:image/png;base64,",
  "claude-code": "data:image/png;base64,",
  "pi": "data:image/svg+xml;base64,",
  "cursor": "data:image/png;base64,",
  "openai": "data:image/png;base64,",
  "anthropic": "data:image/png;base64,",
};

export function getBrandLogoDataUri(id: string): string | null {
  return BRAND_LOGO_DATA_URIS[id] ?? null;
}
